              </td>
              <For each={recipe.variantMap.variant}>
                {(v) => (
                  <td key={v}>
                    <Stack minW="200px">
                      <DemoProgress colorPalette={c} variant={v} value={65} />
                      <DemoProgress
                        colorPalette={c}
                        variant={v}
                        striped
                        value={65}
                      />
                      <DemoProgress
                        colorPalette={c}
                        variant={v}
                        striped
                        animated
                        value={65}
                      />
                    </Stack>
                  </td>
                )}
              </For>
            </tr>
          )}
        </For>
      </tbody>
    </PlaygroundTable>
  )
}

